def atomic_write(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    name = None
    try:
        with tempfile.NamedTemporaryFile(dir=path.parent, delete=False) as handle:
            name = handle.name
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(name, path)
    finally:
        if name is not None:
            Path(name).unlink(missing_ok=True)

def main():
    root = Path.cwd()
    if not (root / 'auditor/scanner.py').is_file():
        raise SystemExit('Run this installer inside ~/owasp-web-auditor.')
    for module in ('jinja2', 'jsonschema'):
        if importlib.util.find_spec(module) is None:
            raise SystemExit('Install dependencies first: .venv/bin/python -m pip install "Jinja2>=3.1.6,<4" "jsonschema>=4.26,<5"')
    for relative, content in FILES.items():
        path = root / relative
        if any(parent.is_symlink() for parent in [path, *path.parents] if parent != root.parent):
            raise SystemExit('Refusing symlink destination: ' + relative)
        actual = path.read_text(encoding='utf-8') if path.exists() else None
        if actual != content and actual != EXPECTED[relative]:
            raise SystemExit('Source differs: ' + relative + '; no changes made.')
        if relative.endswith('.py'):
            compile(content, relative, 'exec')
    changes = {root / name: value.encode('utf-8') for name, value in FILES.items()
               if not (root / name).exists() or (root / name).read_text(encoding='utf-8') != value}
    if not changes:
        print('Project configuration and account sessions are already installed.')
        return
    ignore = root / '.gitignore'
    if ignore.is_symlink():
        raise SystemExit('Refusing symlink .gitignore; no changes made.')
    ignore_text = ignore.read_text(encoding='utf-8') if ignore.exists() else ''
    if '.project-session-backups/' not in ignore_text.splitlines():
        changes[ignore] = (ignore_text.rstrip('\n') + '\n.project-session-backups/\n').encode()
    previous = {path: path.read_bytes() if path.exists() else None for path in changes}
    backup_dir = root / '.project-session-backups'
    if backup_dir.is_symlink():
        raise SystemExit('Refusing symlink backup directory; no changes made.')
    backup_dir.mkdir(exist_ok=True)
    backup = backup_dir / (datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S-%f') + '.zip')
    with zipfile.ZipFile(backup, 'x', zipfile.ZIP_DEFLATED) as archive:
        for path, content in previous.items():
            if content is not None:
                archive.writestr(path.relative_to(root).as_posix(), content)
        archive.writestr('__installation__.json', json.dumps({'new_files': [p.relative_to(root).as_posix() for p, b in previous.items() if b is None]}, indent=2))
    try:
        for path, content in changes.items():
            atomic_write(path, content)
    except BaseException:
        for path, content in previous.items():
            if content is None:
                path.unlink(missing_ok=True)
            else:
                atomic_write(path, content)
        raise
    print('Project configuration and isolated account preflight installed.')
    print('Backup:', backup)
    print('No scans or Git operations were performed.')

if __name__ == '__main__':
    main()
